"use server";

// 1. Yolları (Import Paths) Proje Yapına Göre Düzelttik (@/ işareti src'yi temsil eder)
import { prisma } from "@/lib/prisma"; 
import bcrypt from "bcrypt";
// Role enum'unu direkt Prisma Client'tan çekmek daha güvenlidir
import { Role } from "@prisma/client"; 

export async function register(formData: FormData) {
  // Form verilerini al
  const email = formData.get("email") as string;
  const password = formData.get("password") as string;
  const roleInput = formData.get("role") as string;
  const gender = formData.get("gender") as string;

  // Temel kontrol
  if (!email || !password) {
    return { error: "E-mail en wachtwoord zijn verplicht." };
  }

  try {
    // 2. Kullanıcı kontrolü
    const exists = await prisma.user.findUnique({
      where: { email },
    });

    if (exists) {
      return { error: "Bu e-mail zaten kayıtlı!" };
    }

    // 3. Şifreleme
    const hashed = await bcrypt.hash(password, 10);

    // 4. Rol Belirleme (Enum yapısına tam uygun olmalı)
    // Eğer roleInput boşsa varsayılan USER yap
    let finalRole: Role = Role.USER;
    if (roleInput === "ADMIN") finalRole = Role.ADMIN;
    if (roleInput === "MEDEWERKER") finalRole = Role.MEDEWERKER;

    // 5. Veritabanı Kaydı
    await prisma.user.create({
      data: {
        email: email,
        password: hashed,
        role: finalRole,
        gender: gender || "other",
        name: email.split('@')[0], // Email'in başını isim olarak ata
      },
    });

    return { success: true };
    
  } catch (err: any) {
    // Terminalde gerçek hatayı görmek için burayı logluyoruz
    console.error("❌ REGISTER ERROR:", err);
    
    // Eğer Prisma Enum hatası verirse bunu kullanıcıya gösterme, teknik hata de
    return { error: "Kayıt sırasında bir hata oluştu. (Teknik Detay: " + err.message + ")" };
  }
}